import re
import uuid
from typing import Protocol

# Keys are generated by the server (see new_storage_key), never taken from a client, and must match this shape.
STORAGE_KEY_PATTERN = re.compile(r"^[a-z0-9_-]+(/[a-z0-9_-]+)*\.[a-z0-9]+$")


class StoredObjectNotFoundError(Exception):
    pass


class InvalidStorageKeyError(ValueError):
    pass


def validate_storage_key(key: str) -> str:
    if not STORAGE_KEY_PATTERN.fullmatch(key):
        raise InvalidStorageKeyError(f"Invalid storage key: {key!r}")
    return key


def new_storage_key(folder: str, extension: str) -> str:
    """A fresh, unguessable key such as ``logos/3f2a….png``; the client's file name never becomes a path."""
    return validate_storage_key(f"{folder}/{uuid.uuid4().hex}.{extension}")


class StorageBackend(Protocol):
    """Where uploaded files live. Records in the database keep only the key and the validated content type."""

    async def save(self, key: str, data: bytes, content_type: str) -> None: ...

    async def read(self, key: str) -> bytes: ...

    async def delete(self, key: str) -> None: ...
